// Checks the TypeScript request mirror against the Rust golden contract
// generated by crates/rustward-ipc/tests/contract.rs.
import { describe, expect, it } from "vitest";
import { PRIVILEGED, REQUEST_TYPES } from "../api/types";
import golden from "../../../../crates/rustward-ipc/contract/request-types.json";

interface Contract {
  protocol_version: number;
  requests: { type: string; access: "read_only" | "administrator" }[];
}

const contract: Contract = golden as Contract;

describe("IPC contract", () => {
  it("is protocol version 1", () => {
    expect(contract.protocol_version).toBe(1);
  });

  it("lists exactly the Rust request types, in order", () => {
    expect([...REQUEST_TYPES]).toEqual(contract.requests.map((r) => r.type));
  });

  it("marks exactly the administrator requests as privileged", () => {
    const admin = contract.requests.filter((r) => r.access === "administrator").map((r) => r.type).sort();
    expect([...PRIVILEGED].sort()).toEqual(admin);
  });
});
